@pushOnce('styles', 'crm-rocket-converted-styles')
<style>
.crm-workspace{--rocket-blue:#375dae;--rocket-blue-soft:#eef3ff;--rocket-green:#18705b;--rocket-green-soft:#e9f7f1;--rocket-amber:#875e19;--rocket-amber-soft:#fff6e5;--rocket-violet:#6851a3;--rocket-violet-soft:#f2edff}
.rocket-summary-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}.rocket-summary-card{padding:22px;border:1px solid var(--admin-line);background:var(--admin-panel,#fff);border-radius:20px;display:flex;align-items:center;gap:16px;min-width:0}.rocket-summary-card svg{width:26px;height:26px}.rocket-summary-card .rocket-summary-icon{display:grid;place-items:center;width:52px;height:52px;border-radius:16px;flex:none;background:var(--rocket-blue-soft);color:var(--rocket-blue)}.rocket-summary-card:nth-child(2) .rocket-summary-icon{background:var(--rocket-green-soft);color:var(--rocket-green)}.rocket-summary-card:nth-child(3) .rocket-summary-icon{background:var(--rocket-amber-soft);color:var(--rocket-amber)}.rocket-summary-card:nth-child(4) .rocket-summary-icon{background:var(--rocket-violet-soft);color:var(--rocket-violet)}.rocket-summary-card strong{display:block;font-size:28px;line-height:1.2;font-variant-numeric:tabular-nums}.rocket-summary-card p{margin:5px 0 0;font-size:13px;color:var(--admin-muted)}
.rocket-toolbar,.rocket-section-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap}.rocket-toolbar{margin-top:8px}.rocket-toolbar>div{display:flex;flex-wrap:wrap;gap:8px}.rocket-section-heading{padding:22px 24px;border-bottom:1px solid var(--admin-line)}.rocket-section-heading h2{margin:0;font-size:18px}.rocket-section-heading p{margin:4px 0 0;font-size:13px;color:var(--admin-muted)}.rocket-row-identity{display:flex;align-items:center;gap:12px}.rocket-avatar{display:grid;place-items:center;flex:none;width:44px;height:44px;border-radius:14px;background:var(--rocket-blue-soft);color:var(--rocket-blue);font-size:18px;font-weight:700}.rocket-row-identity>div{min-width:0}.rocket-record-reference{color:var(--admin-muted);font-size:12px;letter-spacing:.06em}.rocket-state{display:inline-flex;align-items:center;gap:6px;background:var(--rocket-green-soft);color:var(--rocket-green);border-radius:8px;padding:5px 10px;font-size:12px;font-weight:600}.rocket-state--muted{background:var(--rocket-blue-soft);color:var(--rocket-blue)}.rocket-state--attention{background:var(--rocket-amber-soft);color:var(--rocket-amber)}.rocket-task-meta{display:flex;flex-wrap:wrap;gap:8px;margin-top:8px}.rocket-empty{padding:48px 24px;text-align:center}.rocket-empty svg{width:76px;height:76px;color:var(--rocket-blue);background:var(--rocket-blue-soft);padding:18px;border-radius:24px}.rocket-empty h2{font-size:20px;margin:18px 0 8px}.rocket-empty p{margin:auto;max-width:48ch;color:var(--admin-muted);line-height:1.7}
.rocket-detail-layout{display:grid;grid-template-columns:minmax(220px,280px) minmax(0,1fr);gap:24px;align-items:start}.rocket-detail-layout>*{min-width:0}.rocket-profile-card{border:1px solid var(--admin-line);border-radius:24px;background:var(--admin-panel,#fff);overflow:hidden}.rocket-profile-cover{height:92px;background:var(--rocket-blue-soft);color:#b5c5ed;overflow:hidden}.rocket-profile-cover svg{width:100%;height:100%}.rocket-profile-inner{padding:0 22px 24px;text-align:center}.rocket-profile-card .profile-avatar-card{display:grid;place-items:center;width:80px;height:80px;margin:-40px auto 14px;position:relative;border:6px solid var(--admin-panel,#fff);border-radius:50%;background:var(--rocket-blue);color:white;font-size:30px;font-weight:700}.rocket-profile-card h2{font-size:21px;margin:8px 0;overflow-wrap:anywhere}.profile-followers-card{display:grid;margin:24px 0 0;text-align:left}.profile-followers-card>div{padding:14px 0;border-top:1px solid var(--admin-line)}.profile-followers-card dt{font-size:12px;color:var(--admin-muted)}.profile-followers-card dd{margin:5px 0 0;font-size:14px;overflow-wrap:anywhere}.rocket-profile-links{display:grid;text-align:left;border-top:1px solid var(--admin-line);padding-top:12px}.rocket-profile-links a{display:flex;justify-content:space-between;align-items:center;min-height:44px;gap:12px;color:var(--admin-ink);font-size:14px;text-decoration:none}.rocket-profile-links a:hover{color:var(--admin-primary)}.rocket-detail-layout .crm-profile-form{margin:0}.rocket-filters-title{font-size:16px;margin:0 0 20px}
@media(max-width:1200px){.rocket-summary-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.rocket-detail-layout{grid-template-columns:minmax(190px,230px) minmax(0,1fr)}}
@media(max-width:760px){.rocket-detail-layout{grid-template-columns:minmax(0,1fr)}.rocket-profile-inner .profile-followers-card{grid-template-columns:repeat(2,minmax(0,1fr));gap:0 20px}.rocket-section-heading{padding:18px}.rocket-summary-card{padding:16px;gap:12px}.rocket-summary-card strong{font-size:24px}}
@media(max-width:420px){.rocket-summary-grid{gap:10px}.rocket-summary-card{align-items:start;flex-direction:column}.rocket-summary-card .rocket-summary-icon{width:40px;height:40px;border-radius:12px}.rocket-summary-card p{font-size:12px}.rocket-profile-inner .profile-followers-card{grid-template-columns:minmax(0,1fr)}}
</style>
@endPushOnce
